"use client";

import React from "react";

interface TerracottaPotMascotProps {
  className?: string;
  size?: "sm" | "md" | "lg" | "xl" | number;
  animate?: boolean;
  ariaLabel?: string;
}

// 100% authentic PocketPot Terracotta Pot Buddy character artwork with transparent antialiased background
const POT_ARTWORK_BASE64 = "data:image/png;base64,";

export const TerracottaPotMascot: React.FC<TerracottaPotMascotProps> = ({
  className = "",
  size = "md",
  animate = false,
  ariaLabel = "PocketPot Terracotta Pot Buddy mascot",
}) => {
  let sizeClass = "";
  let explicitWidth: number | undefined;

  if (typeof size === "number") {
    explicitWidth = size;
  } else {
    switch (size) {
      case "sm":
        sizeClass = "w-16 h-auto";
        break;
      case "md":
        sizeClass = "w-24 sm:w-28 h-auto";
        break;
      case "lg":
        sizeClass = "w-32 sm:w-40 h-auto";
        break;
      case "xl":
        sizeClass = "w-48 sm:w-56 h-auto";
        break;
    }
  }

  return (
    <svg
      viewBox="0 0 271 265"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      className={`${sizeClass} ${className} ${animate ? "animate-bounce-subtle" : ""} select-none drop-shadow-sm`}
      style={explicitWidth ? { width: explicitWidth, height: "auto" } : undefined}
      aria-label={ariaLabel}
      role="img"
    >
      <image
        href={POT_ARTWORK_BASE64}
        width="271"
        height="265"
        preserveAspectRatio="xMidYMid meet"
      />
    </svg>
  );
};

export default TerracottaPotMascot;
